        self.init()
        for field in Self.schema {
            try field.decode(values, &self)
        }
    }

    func encode(to container: inout KeyedEncodingContainer<TriggerCodingKey>) throws {
        for field in Self.schema {
            try field.encode(self, &container)
        }
    }
}
